package com.kidsvideo.app;

import android.app.*;import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;

public class MainActivity extends Activity {
 private Prefs prefs;private YouTubeRepository repo;private SpeechHelper speech;private LinearLayout list,cats;private EditText search;private TextView status;private List<VideoItem>videos=new ArrayList<>();private String category="Home";
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=new Prefs(this);repo=new YouTubeRepository(this);speech=new SpeechHelper(this);build();if(prefs.apiKey().isEmpty()||prefs.parentPin().isEmpty()){startActivity(new Intent(this,ApiSetupActivity.class));}else load();}
 @Override protected void onResume(){super.onResume();if(prefs!=null&&!prefs.apiKey().isEmpty()&&videos.isEmpty())load();}
 private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(15,15,15));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(Ui.dp(this,16),Ui.dp(this,10),Ui.dp(this,16),Ui.dp(this,8));TextView logo=new TextView(this);logo.setText("▶  "+BuildConfig.APP_DISPLAY_NAME);logo.setTextColor(Color.WHITE);logo.setTextSize(Ui.isTv(this)?25:21);logo.setTypeface(null,1);top.addView(logo,new LinearLayout.LayoutParams(0,-2,1));search=new EditText(this);search.setSingleLine(true);search.setHint("Search approved videos");search.setTextColor(Color.WHITE);search.setHintTextColor(Color.GRAY);search.setBackground(Ui.rounded(Color.rgb(35,35,35),22,this));search.setPadding(Ui.dp(this,15),0,Ui.dp(this,15),0);LinearLayout.LayoutParams slp=new LinearLayout.LayoutParams(Ui.isTv(this)?Ui.dp(this,420):0,Ui.dp(this,48));if(!Ui.isTv(this)){slp.width=0;slp.weight=2;}top.addView(search,slp);Button mic=new Button(this);mic.setText("🎤");mic.setContentDescription("Voice search");mic.setOnClickListener(v->voiceSearch());top.addView(mic,new LinearLayout.LayoutParams(Ui.dp(this,62),Ui.dp(this,48)));Button gear=new Button(this);gear.setText("⚙");gear.setContentDescription("Parent settings");gear.setOnClickListener(v->askPin());top.addView(gear,new LinearLayout.LayoutParams(Ui.dp(this,62),Ui.dp(this,48)));root.addView(top);HorizontalScrollView hsv=new HorizontalScrollView(this);hsv.setHorizontalScrollBarEnabled(false);cats=new LinearLayout(this);cats.setOrientation(LinearLayout.HORIZONTAL);cats.setPadding(Ui.dp(this,12),Ui.dp(this,4),Ui.dp(this,12),Ui.dp(this,6));hsv.addView(cats);root.addView(hsv);for(String c:AppConfig.categories()){TextView x=new TextView(this);x.setText(c);x.setTextSize(15);x.setFocusable(true);Ui.styleButton(x,c.equals(category));x.setOnClickListener(v->{category=c;rebuildCategories();render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.setMargins(Ui.dp(this,4),0,Ui.dp(this,4),0);cats.addView(x,lp);}status=new TextView(this);status.setTextColor(Color.LTGRAY);status.setTextSize(14);status.setPadding(Ui.dp(this,18),Ui.dp(this,6),Ui.dp(this,18),Ui.dp(this,6));root.addView(status);ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);list.setPadding(Ui.dp(this,12),0,Ui.dp(this,12),Ui.dp(this,30));sc.addView(list);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));search.setOnEditorActionListener((v,a,e)->{render();return true;});setContentView(root);}
 private void rebuildCategories(){for(int i=0;i<cats.getChildCount();i++){TextView v=(TextView)cats.getChildAt(i);Ui.styleButton(v,v.getText().toString().equals(category));}}
 private void load(){List<VideoItem>cache=prefs.loadVideos();if(!cache.isEmpty()){videos=cache;render();}status.setText("Refreshing approved channels…");repo.refresh(new YouTubeRepository.Callback(){public void onSuccess(List<VideoItem>v){runOnUiThread(()->{videos=v;status.setText(v.size()+" approved long videos");render();});}public void onError(String m){runOnUiThread(()->status.setText("Could not refresh: "+m));}});}
 private void render(){list.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);Set<String>fav=prefs.favorites();List<String>hist=prefs.history();int shown=0;for(VideoItem v:videos){boolean ok=category.equals("Home")||category.equals(v.category)||(category.equals("Favourites")&&fav.contains(v.id))||(category.equals("Watched")&&hist.contains(v.id));if(!ok)continue;if(!q.isEmpty()&&!(v.title.toLowerCase(Locale.ROOT).contains(q)||v.channelTitle.toLowerCase(Locale.ROOT).contains(q)||v.category.toLowerCase(Locale.ROOT).contains(q)))continue;list.addView(card(v));shown++;}if(shown==0){TextView e=new TextView(this);e.setText(q.isEmpty()?"No videos in this section yet.":"No approved videos match ‘"+q+"’. Try a category such as science, animals, space, history or drawing.");e.setTextColor(Color.LTGRAY);e.setTextSize(18);e.setPadding(Ui.dp(this,22),Ui.dp(this,30),Ui.dp(this,22),Ui.dp(this,30));list.addView(e);}}
 private View card(VideoItem v){LinearLayout row=new LinearLayout(this);row.setOrientation(Ui.isTv(this)?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);row.setPadding(Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,14));row.setFocusable(true);row.setClickable(true);row.setBackground(Ui.rounded(Color.rgb(25,25,25),12,this));ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setBackgroundColor(Color.DKGRAY);int w=Ui.isTv(this)?Ui.dp(this,300):-1;row.addView(im,new LinearLayout.LayoutParams(w,Ui.dp(this,169)));ThumbnailLoader.load(im,v.thumbnailUrl);LinearLayout meta=new LinearLayout(this);meta.setOrientation(LinearLayout.VERTICAL);meta.setPadding(Ui.dp(this,14),Ui.dp(this,8),Ui.dp(this,8),Ui.dp(this,8));TextView title=new TextView(this);title.setText(v.title);title.setTextColor(Color.WHITE);title.setTextSize(Ui.isTv(this)?20:17);title.setTypeface(null,1);meta.addView(title);TextView sub=new TextView(this);sub.setText(v.channelTitle+"  •  "+v.category+"  •  "+v.durationLabel());sub.setTextColor(Color.LTGRAY);sub.setTextSize(14);meta.addView(sub);Button fav=new Button(this);fav.setText(prefs.isFavorite(v.id)?"★ Favourite":"☆ Favourite");fav.setAllCaps(false);fav.setOnClickListener(x->{prefs.toggleFavorite(v.id);render();});meta.addView(fav,new LinearLayout.LayoutParams(-2,-2));row.addView(meta,new LinearLayout.LayoutParams(Ui.isTv(this)?0:-1,-2,Ui.isTv(this)?1:0));row.setOnClickListener(x->open(v));row.setOnFocusChangeListener((x,f)->Ui.focusScale(x,f));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,Ui.dp(this,6),0,Ui.dp(this,6));row.setLayoutParams(lp);return row;}
 private void open(VideoItem v){TimeLimit t=new TimeLimit(this);if(!t.canWatch()){new AlertDialog.Builder(this).setTitle("Viewing time finished").setMessage("The parent-set viewing limit has been reached for today.").setPositiveButton("OK",null).show();return;}prefs.addHistory(v.id);Intent i=new Intent(this,PlayerActivity.class);i.putExtra("id",v.id);i.putExtra("title",v.title);startActivity(i);}
 private void voiceSearch(){status.setText("Listening…");speech.listen(prefs.voiceLocale(),new SpeechHelper.Callback(){public void onResult(String t){runOnUiThread(()->{search.setText(t);status.setText("You said: "+t);render();});}public void onError(String m){runOnUiThread(()->status.setText(m));}});}
 private void askPin(){EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);new AlertDialog.Builder(this).setTitle("Parent PIN").setView(e).setPositiveButton("Open",(d,w)->{if(e.getText().toString().equals(prefs.parentPin()))startActivity(new Intent(this,ParentSettingsActivity.class));else Toast.makeText(this,"Incorrect PIN",Toast.LENGTH_SHORT).show();}).setNegativeButton("Cancel",null).show();}
 @Override protected void onDestroy(){super.onDestroy();if(repo!=null)repo.shutdown();if(speech!=null)speech.destroy();}
}
